+      code.insts()->maybe_expand_to_ensure_remaining(1024);
+      ASSERT_NE(code.stubs()->start(), stubs_before);
+      EXPECT_EQ(code.static_call_dispatch_adapter_offset(), 0);
+    }
+  }
+
+  for (int i = 0; i < N; i++) {
